int dfs(vector<int>& boxes, int dp[100][100][100], int l, int r, int k) {
    if (l > r) return 0;
    if (dp[l][r][k] != 0) return dp[l][r][k];

    while (r > l && boxes[r] == boxes[r - 1]) {r--; k++;}

