int shortestPathLength(const std::vector<std::vector<int>>& graph) {
    int n = graph.size();
    std::queue<std::tuple<int, int, int>> q;
    std::vector<std::vector<bool>> visited(n, std::vector<bool>(1 << n, false));

    for (int i = 0; i < n; ++i) {
        q.push({i, 1 << i, 0});
