    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int color = targetGrid[i][j];
            colorBounds.putIfAbsent(color, new int[] {i, j, i, j});
            colorBounds.get(color)[0] = Math.min(colorBounds.get(color)[0], i);
            colorBounds.get(color)[1] = Math.min(colorBounds.get(color)[1], j);
