public class CF289F {
    static int[] a;
    static int[][] dp;
    static int MOD = 1_000_000_007;

    static int f(int l, int r) {
        if (l >= r)
            return 1;
        if (dp[l][r] != -1)
            return dp[l][r];
        long answer = 0;
        for (int k = l + 1; k <= r + 1; k++)
