            copy(dp, dp_prev);

            for (int i = 0; i < 3; i++)
                for (int j = 0; j < 3; j++) {
                    if (i == j) continue;

                    int other = other(i, j);
                    long cost1 = dp_prev[i][other] + t[i][j] + dp_prev[other][j];
                    long cost2 = dp_prev[i][j] + t[i][other] + dp_prev[j][i] + t[other][j] + dp_prev[i][j];
                    dp[i][j] = Math.min(cost1, cost2);
                }
        }

        out.println(dp[0][2]);
        out.flush();
    }

    private static void copy(long[][] from, long[][] to) {
        for (int i = 0; i < 3; i++)
