	static int[][][] dp;

	static int solve(int i, int n, int dir) {
		if (i == s.length)
			return n == 0 ? 0 : -999999;
		if (dp[i][n][dir] != -1)
			return dp[i][n][dir];
		int ans = (s[i] == 'F' ? (dir == 0 ? 1 : -1) : 0)
				+ solve(i + 1, n, s[i] != 'F' ? 1 - dir : dir);
		for (int j = 1; j <= n; j++) {
